{
  "name": "opencode-claude-auth-custom",
  "version": "1.0.3",
  "description": "OpenCode plugin that routes Claude Code OAuth credentials through a custom base URL (e.g. LiteLLM) using ANTHROPIC_BASE_URL and ANTHROPIC_CUSTOM_HEADERS.",
  "keywords": [
    "anthropic",
    "auth",
    "claude",
    "opencode",
    "plugin",
    "litellm"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ichasco/opencode-claude-auth-custom.git"
  },
  "type": "module",
  "main": "opencode-claude-auth-custom.js",
  "module": "opencode-claude-auth-custom.js",
  "exports": {
    ".": {
      "import": "./opencode-claude-auth-custom.js"
    }
  },
  "files": [
    "opencode-claude-auth-custom.js"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  }
}
